{"version":3,"sources":["..\\scss\\_storesListItem.scss","stores.css","..\\scss\\_mixins.scss","..\\scss\\_variables.scss","..\\scss\\stores.scss"],"names":[],"mappings":"AAAA;EACE,aAAA;EACA,SAAA;EACA,oBAAA;EACA,gCAAA;ACCF;;ADEA;EACE,aAAA;EACA,sBAAA;EACA,SAAA;ACCF;;ADEA;EACE,eAAA;EACA,cAAA;ACCF;ADAE;EACE,iBAAA;EACA,WAAA;EACA,YAAA;EACA,sBAAA;KAAA,mBAAA;EACA,0BAAA;KAAA,uBAAA;ACEJ;;ADEA;EACE,eAAA;ACCF;ADAE;EE1BA,uCAAA;EACA,gBF0BmC;EEzBnC,kBAAA;EACA,cCJU;EDKV,eFuB6B;ACM/B;ADJI;EACE,UG7BO;AFmCb;ADHE;EEjCA,uCAAA;EACA,gBFiCsC;EEhCtC,kBAAA;EACA,YCHa;EDIb,eF8BgC;ACSlC;;ADLA;EACE,yBAAA;ACQF;;ADLA;EE1CE,uCAAA;EACA,gBF0C8B;EEzC9B,kBAAA;EACA,cFwCe;EEvCf,eFuCwB;ACY1B;;AGpDA;EACE,gBAAA;EACA,oBAAA;EACA,gCAAA;AHuDF;;AGpDA;EFTE,uCAAA;EACA,gBESoC;EFRpC,kBAAA;EACA,YCHa;EDIb,eEM8B;EAC9B,mBAAA;AH2DF;;AGxDA;EACE,aAAA;EACA,4DAAA;AH2DF;AGzDE;EFlBA,uCAAA;EACA,gBEkBmC;EFjBnC,kBAAA;EACA,cCJU;EDKV,eEe6B;AH+D/B;AG7DI;EACE,UDrBO;AFoFb;;AG1DA;EACE,gBAAA;AH6DF;;AG3DA;EACE,aAAA;EACA,sBAAA;EACA,SAAA;AH8DF","file":"stores.css","sourcesContent":[".stores__list-item {\r\n  display: flex;\r\n  gap: 10px;\r\n  padding-bottom: 10px;\r\n  border-bottom: 1px solid $gray;\r\n}\r\n\r\n.stores__list-item-about {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 10px;\r\n}\r\n\r\n.stores__list-item-img {\r\n  flex: 0 0 160px;\r\n  display: block;\r\n  & img {\r\n    max-height: 120px;\r\n    width: 100%;\r\n    height: 100%;\r\n    object-fit: contain;\r\n    object-position: center;\r\n  }\r\n}\r\n\r\n.stores__list-item-about {\r\n  flex: 0 1 300px;\r\n  & a {\r\n    @include fonts($mainColor, 18px, 600);\r\n\r\n    &:hover {\r\n      color: $colorHover;\r\n    }\r\n  }\r\n  & p {\r\n    @include fonts($defaultColor, 14px, 400);\r\n  }\r\n}\r\n\r\n.stores__list-item-district {\r\n  color: #545454 !important;\r\n}\r\n\r\n.stores__list-item-category {\r\n  @include fonts(#545454, 14px, 400);\r\n}\r\n",".stores__list-item {\n  display: flex;\n  gap: 10px;\n  padding-bottom: 10px;\n  border-bottom: 1px solid #D4D4D4;\n}\n\n.stores__list-item-about {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n\n.stores__list-item-img {\n  flex: 0 0 160px;\n  display: block;\n}\n.stores__list-item-img img {\n  max-height: 120px;\n  width: 100%;\n  height: 100%;\n  object-fit: contain;\n  object-position: center;\n}\n\n.stores__list-item-about {\n  flex: 0 1 300px;\n}\n.stores__list-item-about a {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 600;\n  font-style: normal;\n  color: #3077a0;\n  font-size: 18px;\n}\n.stores__list-item-about a:hover {\n  color: red;\n}\n.stores__list-item-about p {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 14px;\n}\n\n.stores__list-item-district {\n  color: #545454 !important;\n}\n\n.stores__list-item-category {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: #545454;\n  font-size: 14px;\n}\n\n.category_navigation_bar {\n  margin-top: 10px;\n  padding-bottom: 10px;\n  border-bottom: 1px solid #D4D4D4;\n}\n\n.number_of_advertisements {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 14px;\n  margin: 10px 0 20px;\n}\n\n.category_list {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));\n}\n.category_list a {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: #3077a0;\n  font-size: 14px;\n}\n.category_list a:hover {\n  color: red;\n}\n\n.stores {\n  margin-top: 20px;\n}\n\n.stores__list {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}","@mixin fonts($color,$size,$weight) {\r\n  font-family: 'Trebuchet MS', sans-serif;\r\n  font-weight: $weight;\r\n  font-style: normal;\r\n  color: $color;\r\n  font-size: $size;\r\n}","$mainColor: #3077a0;\r\n$defaultColor: black;\r\n$colorHover: red;\r\n$headerTopBorder: #bdd4e2;\r\n$buttonBg:linear-gradient(0deg, #4d95d6,#6e93dd,#c2d6f4);;\r\n$gray: #D4D4D4;\r\n$vipBg: #ff6163;\r\n$activeItem: #FFFFCA;\r\n$userSearchBg: #CFE6FE;\r\n$asideLinksColor: #307792;\r\n$asideExitColor: rgb(0, 128, 0);","@import \"./variables\";\r\n@import \"./mixins\";\r\n@import \"./storesListItem\";\r\n\r\n.category_navigation_bar {\r\n  margin-top: 10px;\r\n  padding-bottom: 10px;\r\n  border-bottom: 1px solid $gray;\r\n}\r\n\r\n.number_of_advertisements {\r\n  @include fonts($defaultColor, 14px, 400);\r\n  margin: 10px 0 20px;\r\n}\r\n\r\n.category_list {\r\n  display: grid;\r\n  grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));\r\n\r\n  & a {\r\n    @include fonts($mainColor, 14px, 400);\r\n\r\n    &:hover {\r\n      color: $colorHover;\r\n    }\r\n  }\r\n}\r\n\r\n.stores {\r\n  margin-top: 20px;\r\n}\r\n.stores__list {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 10px;\r\n}"]}{\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 10px;\r\n}"]}